import{_ as t,o as a,h as r,a2 as s}from"./chunks/framework.wsBNORhl.js";const h=JSON.parse('{"title":"@ui5/project/build/helpers/TaskUtil","description":"","frontmatter":{"prev":false,"next":false},"headers":[],"relativePath":"api/@ui5_project_build_helpers_TaskUtil.md","filePath":"api/@ui5_project_build_helpers_TaskUtil.md"}'),o={name:"api/@ui5_project_build_helpers_TaskUtil.md"};function i(n,e,l,c,d,p){return a(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="ui5-project-build-helpers-taskutil" tabindex="-1">@ui5/project/build/helpers/TaskUtil <a class="header-anchor" href="#ui5-project-build-helpers-taskutil" aria-label="Permalink to &quot;@ui5/project/build/helpers/TaskUtil&quot;">​</a></h1><h2 id="ui5-project-build-helpers-taskutil-1" tabindex="-1">@ui5/project/build/helpers/TaskUtil <a class="header-anchor" href="#ui5-project-build-helpers-taskutil-1" aria-label="Permalink to &quot;@ui5/project/build/helpers/TaskUtil&quot;">​</a></h2><p>Convenience functions for UI5 tasks. An instance of this class is passed to every standard UI5 task that requires it.</p><p>Custom tasks that define a specification version &gt;= 2.2 will receive an interface to an instance of this class when called. The set of available functions on that interface depends on the specification version defined for the extension.</p><h3 id="members" tabindex="-1">Members <a class="header-anchor" href="#members" aria-label="Permalink to &quot;Members&quot;">​</a></h3><h4 id="standard-tags-ui5-project-build-helpers-taskutil-standardbuildtags" tabindex="-1"><div class="jsdoc-object" id="STANDARD_TAGS"><span class="type-signature"></span>STANDARD_TAGS<span class="type-signature"> :<a href="@ui5_project_build_helpers_TaskUtil#~StandardBuildTags">@ui5/project/build/helpers/TaskUtil~StandardBuildTags</a></span></div> <a class="header-anchor" href="#standard-tags-ui5-project-build-helpers-taskutil-standardbuildtags" aria-label="Permalink to &quot;&lt;div class=&#39;jsdoc-object&#39; id=&#39;STANDARD_TAGS&#39;&gt;&lt;span class=&quot;type-signature&quot;&gt;&lt;/span&gt;STANDARD_TAGS&lt;span class=&quot;type-signature&quot;&gt; :&lt;a href=&quot;@ui5_project_build_helpers_TaskUtil#~StandardBuildTags&quot;&gt;@ui5/project/build/helpers/TaskUtil~StandardBuildTags&lt;/a&gt;&lt;/span&gt;&lt;/div&gt;&quot;">​</a></h4><p><strong>Source:</strong> <a href="https://github.com/UI5/cli/blob/main/packages//project/lib/build/helpers/TaskUtil.js" target="_blank" rel="noopener noreferrer">project/lib/build/helpers/TaskUtil.js</a>, <a href="https://github.com/UI5/cli/blob/main/packages//project/lib/build/helpers/TaskUtil.js#L59" target="_blank" rel="noopener noreferrer">line 59</a></p><h5 id="type" tabindex="-1">Type: <a class="header-anchor" href="#type" aria-label="Permalink to &quot;Type:&quot;">​</a></h5><ul><li><a href="@ui5_project_build_helpers_TaskUtil#~StandardBuildTags">@ui5/project/build/helpers/TaskUtil~StandardBuildTags</a></li></ul><h4 id="resourcefactory-ui5-project-build-helpers-taskutil-resourcefactory" tabindex="-1"><div class="jsdoc-object" id="resourceFactory"><span class="type-signature"></span>resourceFactory<span class="type-signature"> :<a href="@ui5_project_build_helpers_TaskUtil#~resourceFactory">@ui5/project/build/helpers/TaskUtil~resourceFactory</a></span></div> <a class="header-anchor" href="#resourcefactory-ui5-project-build-helpers-taskutil-resourcefactory" aria-label="Permalink to &quot;&lt;div class=&#39;jsdoc-object&#39; id=&#39;resourceFactory&#39;&gt;&lt;span class=&quot;type-signature&quot;&gt;&lt;/span&gt;resourceFactory&lt;span class=&quot;type-signature&quot;&gt; :&lt;a href=&quot;@ui5_project_build_helpers_TaskUtil#~resourceFactory&quot;&gt;@ui5/project/build/helpers/TaskUtil~resourceFactory&lt;/a&gt;&lt;/span&gt;&lt;/div&gt;&quot;">​</a></h4><p><strong>Description:</strong> Provides limited access to @ui5/fs/resourceFactory functions</p><p> This attribute is only available to custom task extensions defining <b>Specification Version 3.0 and above</b>.</p><p><strong>Source:</strong> <a href="https://github.com/UI5/cli/blob/main/packages//project/lib/build/helpers/TaskUtil.js" target="_blank" rel="noopener noreferrer">project/lib/build/helpers/TaskUtil.js</a>, <a href="https://github.com/UI5/cli/blob/main/packages//project/lib/build/helpers/TaskUtil.js#L377" target="_blank" rel="noopener noreferrer">line 377</a></p><p>Provides limited access to @ui5/fs/resourceFactory functions</p><p> This attribute is only available to custom task extensions defining <b>Specification Version 3.0 and above</b>.</p><h5 id="type-1" tabindex="-1">Type: <a class="header-anchor" href="#type-1" aria-label="Permalink to &quot;Type:&quot;">​</a></h5><ul><li><a href="@ui5_project_build_helpers_TaskUtil#~resourceFactory">@ui5/project/build/helpers/TaskUtil~resourceFactory</a></li></ul><h3 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to &quot;Methods&quot;">​</a></h3><h4 id="cleartag-resource-tag" tabindex="-1"><div class="jsdoc-object" id="clearTag"><span class="type-signature"></span>clearTag<span class="signature">(resource, tag)</span><span class="type-signature"></span></div> <a class="header-anchor" href="#cleartag-resource-tag" aria-label="Permalink to &quot;&lt;div class=&#39;jsdoc-object&#39; id=&#39;clearTag&#39;&gt;&lt;span class=&quot;type-signature&quot;&gt;&lt;/span&gt;clearTag&lt;span class=&quot;signature&quot;&gt;(resource, tag)&lt;/span&gt;&lt;span class=&quot;type-signature&quot;&gt;&lt;/span&gt;&lt;/div&gt;&quot;">​</a></h4><p><strong>Description:</strong> Clears the value of a tag stored for the given resource&#39;s path. It&#39;s like the tag was never set for that resource.</p><p> This method is only available to custom task extensions defining <b>Specification Version 2.2 and above</b>.</p><p><strong>Source:</strong> <a href="https://github.com/UI5/cli/blob/main/packages//project/lib/build/helpers/TaskUtil.js" target="_blank" rel="noopener noreferrer">project/lib/build/helpers/TaskUtil.js</a>, <a href="https://github.com/UI5/cli/blob/main/packages//project/lib/build/helpers/TaskUtil.js#L132" target="_blank" rel="noopener noreferrer">line 132</a></p><h5 id="parameters" tabindex="-1">Parameters: <a class="header-anchor" href="#parameters" aria-label="Permalink to &quot;Parameters:&quot;">​</a></h5><table tabindex="0"><thead><tr><th>Name</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>resource</code></td><td><a href="@ui5_fs_Resource">@ui5/fs/Resource</a></td><td>Resource-instance the tag should be cleared for</td></tr><tr><td><code>tag</code></td><td>string</td><td>Tag</td></tr></tbody></table><h4 id="getbuildtime-rarr-date" tabindex="-1"><div class="jsdoc-object" id="getBuildTime"><span class="type-signature"></span>getBuildTime<span class="signature">()</span><span class="type-signature"> → {Date}</span></div> <a class="header-anchor" href="#getbuildtime-rarr-date" aria-label="Permalink to &quot;&lt;div class=&#39;jsdoc-object&#39; id=&#39;getBuildTime&#39;&gt;&lt;span class=&quot;type-signature&quot;&gt;&lt;/span&gt;getBuildTime&lt;span class=&quot;signature&quot;&gt;()&lt;/span&gt;&lt;span class=&quot;type-signature&quot;&gt; &amp;rarr; {Date}&lt;/span&gt;&lt;/div&gt;&quot;">​</a></h4><p><strong>Description:</strong> Returns the build run&#39;s shared timestamp as a raw <code>Date</code>.</p><p>The value is the single timestamp fixed once per build run (shared by every project and task in the run), the same source <a href="@ui5_project_build_helpers_TaskUtil#getTime">getTime</a> quantizes.</p><p>Unlike <code>getTime</code>, this read is deliberately <b>not</b> tracked as a build-cache input: the MonitoredTaskUtil passes it through untracked, so its value never folds into the task&#39;s cache signature. A cached result therefore keeps the timestamp it embedded on the build that produced it, rather than re-running because the timestamp advanced. That staleness is intended: a build timestamp changes on every build, so tracking it would force a cache miss every time and defeat caching for any task that reads it. Read through <code>getTime</code> instead when the output should re-run once a time bucket rolls over (for example a copyright year).</p><p> This method is only available to custom task extensions defining <b>Specification Version 5.0 and above</b>.</p><p><strong>Source:</strong> <a href="https://github.com/UI5/cli/blob/main/packages//project/lib/build/helpers/TaskUtil.js" target="_blank" rel="noopener noreferrer">project/lib/build/helpers/TaskUtil.js</a>, <a href="https://github.com/UI5/cli/blob/main/packages//project/lib/build/helpers/TaskUtil.js#L222" target="_blank" rel="noopener noreferrer">line 222</a></p><h5 id="returns" tabindex="-1">Returns: <a class="header-anchor" href="#returns" aria-label="Permalink to &quot;Returns:&quot;">​</a></h5><p>The current build run&#39;s timestamp</p><p><strong>Type:</strong> Date</p><h4 id="getdependencies-projectnameopt-rarr-array-lt-string" tabindex="-1"><div class="jsdoc-object" id="getDependencies"><span class="type-signature"></span>getDependencies<span class="signature">(projectName<span class="signature-attributes">opt</span>)</span><span class="type-signature"> → {Array&lt;string&gt;}</span></div> <a class="header-anchor" href="#getdependencies-projectnameopt-rarr-array-lt-string" aria-label="Permalink to &quot;&lt;div class=&#39;jsdoc-object&#39; id=&#39;getDependencies&#39;&gt;&lt;span class=&quot;type-signature&quot;&gt;&lt;/span&gt;getDependencies&lt;span class=&quot;signature&quot;&gt;(projectName&lt;span class=&quot;signature-attributes&quot;&gt;opt&lt;/span&gt;)&lt;/span&gt;&lt;span class=&quot;type-signature&quot;&gt; &amp;rarr; {Array&amp;lt;string&gt;}&lt;/span&gt;&lt;/div&gt;&quot;">​</a></h4><p><strong>Description:</strong> Retrieve a list of direct dependencies of a given project from the dependency graph. Note that this list does not include transitive dependencies.</p><p> This method is only available to custom task extensions defining <b>Specification Version 3.0 and above</b>.</p><p><strong>Source:</strong> <a href="https://github.com/UI5/cli/blob/main/packages//project/lib/build/helpers/TaskUtil.js" target="_blank" rel="noopener noreferrer">project/lib/build/helpers/TaskUtil.js</a>, <a href="https://github.com/UI5/cli/blob/main/packages//project/lib/build/helpers/TaskUtil.js#L342" target="_blank" rel="noopener noreferrer">line 342</a></p><h5 id="parameters-1" tabindex="-1">Parameters: <a class="header-anchor" href="#parameters-1" aria-label="Permalink to &quot;Parameters:&quot;">​</a></h5><table tabindex="0"><thead><tr><th>Name</th><th>Type</th><th>Attributes</th><th>Description</th></tr></thead><tbody><tr><td><code>projectName</code></td><td>string</td><td>optional</td><td>Name of the project to retrieve. Defaults to the project currently being built</td></tr></tbody></table><h5 id="throws" tabindex="-1">Throws: <a class="header-anchor" href="#throws" aria-label="Permalink to &quot;Throws:&quot;">​</a></h5><p>If the requested project is unknown to the graph</p><p><strong>Type:</strong> Error</p><h5 id="returns-1" tabindex="-1">Returns: <a class="header-anchor" href="#returns-1" aria-label="Permalink to &quot;Returns:&quot;">​</a></h5><p>Names of all direct dependencies</p><p><strong>Type:</strong> Array&lt;string&gt;</p><h4 id="getenv-name-rarr-string-undefined" tabindex="-1"><div class="jsdoc-object" id="getEnv"><span class="type-signature"></span>getEnv<span class="signature">(name)</span><span class="type-signature"> → {string|undefined}</span></div> <a class="header-anchor" href="#getenv-name-rarr-string-undefined" aria-label="Permalink to &quot;&lt;div class=&#39;jsdoc-object&#39; id=&#39;getEnv&#39;&gt;&lt;span class=&quot;type-signature&quot;&gt;&lt;/span&gt;getEnv&lt;span class=&quot;signature&quot;&gt;(name)&lt;/span&gt;&lt;span class=&quot;type-signature&quot;&gt; &amp;rarr; {string|undefined}&lt;/span&gt;&lt;/div&gt;&quot;">​</a></h4><p><strong>Description:</strong> Reads an environment variable.</p><p>Tasks whose output depends on an environment variable must read it through this method rather than accessing <code>process.env</code> directly. During a build the task receives a MonitoredTaskUtil that records the read and folds it into the task&#39;s build-cache signature, so that changing the variable between builds invalidates the task&#39;s cached result (the same way a changed resource does). Reading <code>process.env</code> directly is not tracked and can lead to a stale cached result being served.</p><p> This method is only available to custom task extensions defining <b>Specification Version 5.0 and above</b>.</p><p><strong>Source:</strong> <a href="https://github.com/UI5/cli/blob/main/packages//project/lib/build/helpers/TaskUtil.js" target="_blank" rel="noopener noreferrer">project/lib/build/helpers/TaskUtil.js</a>, <a href="https://github.com/UI5/cli/blob/main/packages//project/lib/build/helpers/TaskUtil.js#L160" target="_blank" rel="noopener noreferrer">line 160</a></p><h5 id="parameters-2" tabindex="-1">Parameters: <a class="header-anchor" href="#parameters-2" aria-label="Permalink to &quot;Parameters:&quot;">​</a></h5><table tabindex="0"><thead><tr><th>Name</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>name</code></td><td>string</td><td>Environment variable name</td></tr></tbody></table><h5 id="returns-2" tabindex="-1">Returns: <a class="header-anchor" href="#returns-2" aria-label="Permalink to &quot;Returns:&quot;">​</a></h5><p>The environment variable value, or <code>undefined</code> if unset</p><p><strong>Type:</strong> string | undefined</p><h4 id="getproject-projectnameorresourceopt-rarr-ui5-project-build-helpers-taskutil-projectinterface-undefined" tabindex="-1"><div class="jsdoc-object" id="getProject"><span class="type-signature"></span>getProject<span class="signature">(projectNameOrResource<span class="signature-attributes">opt</span>)</span><span class="type-signature"> → {<a href="@ui5_project_build_helpers_TaskUtil#~ProjectInterface">@ui5/project/build/helpers/TaskUtil~ProjectInterface</a>|undefined}</span></div> <a class="header-anchor" href="#getproject-projectnameorresourceopt-rarr-ui5-project-build-helpers-taskutil-projectinterface-undefined" aria-label="Permalink to &quot;&lt;div class=&#39;jsdoc-object&#39; id=&#39;getProject&#39;&gt;&lt;span class=&quot;type-signature&quot;&gt;&lt;/span&gt;getProject&lt;span class=&quot;signature&quot;&gt;(projectNameOrResource&lt;span class=&quot;signature-attributes&quot;&gt;opt&lt;/span&gt;)&lt;/span&gt;&lt;span class=&quot;type-signature&quot;&gt; &amp;rarr; {&lt;a href=&quot;@ui5_project_build_helpers_TaskUtil#~ProjectInterface&quot;&gt;@ui5/project/build/helpers/TaskUtil~ProjectInterface&lt;/a&gt;|undefined}&lt;/span&gt;&lt;/div&gt;&quot;">​</a></h4><p><strong>Description:</strong> Retrieve a single project from the dependency graph</p><p> This method is only available to custom task extensions defining <b>Specification Version 3.0 and above</b>.</p><p><strong>Source:</strong> <a href="https://github.com/UI5/cli/blob/main/packages//project/lib/build/helpers/TaskUtil.js" target="_blank" rel="noopener noreferrer">project/lib/build/helpers/TaskUtil.js</a>, <a href="https://github.com/UI5/cli/blob/main/packages//project/lib/build/helpers/TaskUtil.js#L315" target="_blank" rel="noopener noreferrer">line 315</a></p><h5 id="parameters-3" tabindex="-1">Parameters: <a class="header-anchor" href="#parameters-3" aria-label="Permalink to &quot;Parameters:&quot;">​</a></h5><table tabindex="0"><thead><tr><th>Name</th><th>Type</th><th>Attributes</th><th>Description</th></tr></thead><tbody><tr><td><code>projectNameOrResource</code></td><td>string | <a href="@ui5_fs_Resource">@ui5/fs/Resource</a></td><td>optional</td><td>Name of the project to retrieve or a Resource instance to retrieve the associated project for.<br>Defaults to the name of the project currently being built</td></tr></tbody></table><h5 id="returns-3" tabindex="-1">Returns: <a class="header-anchor" href="#returns-3" aria-label="Permalink to &quot;Returns:&quot;">​</a></h5><p>Specification Version-dependent interface to the Project instance or <code>undefined</code> if the project name is unknown or the provided resource is not associated with any project.</p><p><strong>Type:</strong> <a href="@ui5_project_build_helpers_TaskUtil#~ProjectInterface">@ui5/project/build/helpers/TaskUtil~ProjectInterface</a> | undefined</p><h4 id="gettag-resource-tag-rarr-string-boolean-integer-undefined" tabindex="-1"><div class="jsdoc-object" id="getTag"><span class="type-signature"></span>getTag<span class="signature">(resource, tag)</span><span class="type-signature"> → {string|boolean|integer|undefined}</span></div> <a class="header-anchor" href="#gettag-resource-tag-rarr-string-boolean-integer-undefined" aria-label="Permalink to &quot;&lt;div class=&#39;jsdoc-object&#39; id=&#39;getTag&#39;&gt;&lt;span class=&quot;type-signature&quot;&gt;&lt;/span&gt;getTag&lt;span class=&quot;signature&quot;&gt;(resource, tag)&lt;/span&gt;&lt;span class=&quot;type-signature&quot;&gt; &amp;rarr; {string|boolean|integer|undefined}&lt;/span&gt;&lt;/div&gt;&quot;">​</a></h4><p><strong>Description:</strong> Retrieves the value for a stored tag. If no value is stored, <code>undefined</code> is returned.</p><p> This method is only available to custom task extensions defining <b>Specification Version 2.2 and above</b>.</p><p><strong>Source:</strong> <a href="https://github.com/UI5/cli/blob/main/packages//project/lib/build/helpers/TaskUtil.js" target="_blank" rel="noopener noreferrer">project/lib/build/helpers/TaskUtil.js</a>, <a href="https://github.com/UI5/cli/blob/main/packages//project/lib/build/helpers/TaskUtil.js#L111" target="_blank" rel="noopener noreferrer">line 111</a></p><h5 id="parameters-4" tabindex="-1">Parameters: <a class="header-anchor" href="#parameters-4" aria-label="Permalink to &quot;Parameters:&quot;">​</a></h5><table tabindex="0"><thead><tr><th>Name</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>resource</code></td><td><a href="@ui5_fs_Resource">@ui5/fs/Resource</a></td><td>Resource-instance the tag should be retrieved for</td></tr><tr><td><code>tag</code></td><td>string</td><td>Name of the tag</td></tr></tbody></table><h5 id="returns-4" tabindex="-1">Returns: <a class="header-anchor" href="#returns-4" aria-label="Permalink to &quot;Returns:&quot;">​</a></h5><p>Tag value for the given resource. <code>undefined</code> if no value is available</p><p><strong>Type:</strong> string | boolean | integer | undefined</p><h4 id="gettime-granularity-rarr-string" tabindex="-1"><div class="jsdoc-object" id="getTime"><span class="type-signature"></span>getTime<span class="signature">(granularity)</span><span class="type-signature"> → {string}</span></div> <a class="header-anchor" href="#gettime-granularity-rarr-string" aria-label="Permalink to &quot;&lt;div class=&#39;jsdoc-object&#39; id=&#39;getTime&#39;&gt;&lt;span class=&quot;type-signature&quot;&gt;&lt;/span&gt;getTime&lt;span class=&quot;signature&quot;&gt;(granularity)&lt;/span&gt;&lt;span class=&quot;type-signature&quot;&gt; &amp;rarr; {string}&lt;/span&gt;&lt;/div&gt;&quot;">​</a></h4><p><strong>Description:</strong> Reads the build&#39;s time quantized to a fixed granularity.</p><p>The returned value comes from a single timestamp fixed once per build run (shared by every project and task in the run), not a fresh <code>Date</code> per call, so all time reads within a run agree.</p><p>Tasks whose output depends on the current time (for example replaceCopyright, which expands <code>${currentYear}</code>) must read it through this method rather than calling <code>new Date()</code> directly. During a build the task receives a MonitoredTaskUtil that records the read and folds it into the task&#39;s build-cache signature, so a cached result re-runs once the time bucket rolls over (a <code>&quot;year&quot;</code>-granularity result is re-run at the next calendar year). A direct <code>Date</code> read is not tracked and can serve a stale result.</p><p>The granularity is the contract: it names the bucket at which the output is stable. A millisecond-precision read would change on every build and miss the cache every time, so this method never returns a raw timestamp. Reading at <code>&quot;year&quot;</code> means &quot;re-run only when the year changes&quot;.</p><p> This method is only available to custom task extensions defining <b>Specification Version 5.0 and above</b>.</p><p><strong>Source:</strong> <a href="https://github.com/UI5/cli/blob/main/packages//project/lib/build/helpers/TaskUtil.js" target="_blank" rel="noopener noreferrer">project/lib/build/helpers/TaskUtil.js</a>, <a href="https://github.com/UI5/cli/blob/main/packages//project/lib/build/helpers/TaskUtil.js#L196" target="_blank" rel="noopener noreferrer">line 196</a></p><h5 id="parameters-5" tabindex="-1">Parameters: <a class="header-anchor" href="#parameters-5" aria-label="Permalink to &quot;Parameters:&quot;">​</a></h5><table tabindex="0"><thead><tr><th>Name</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>granularity</code></td><td>string</td><td>Time bucket, one of <code>&quot;year&quot;</code>, <code>&quot;month&quot;</code>,<br> <code>&quot;day&quot;</code>, <code>&quot;hour&quot;</code></td></tr></tbody></table><h5 id="throws-1" tabindex="-1">Throws: <a class="header-anchor" href="#throws-1" aria-label="Permalink to &quot;Throws:&quot;">​</a></h5><p>If the granularity is not one of the supported buckets</p><p><strong>Type:</strong> Error</p><h5 id="returns-5" tabindex="-1">Returns: <a class="header-anchor" href="#returns-5" aria-label="Permalink to &quot;Returns:&quot;">​</a></h5><p>Current time quantized to the granularity, e.g. <code>&quot;2026&quot;</code> for <code>&quot;year&quot;</code> or <code>&quot;2026-09-25T14&quot;</code> for <code>&quot;hour&quot;</code></p><p><strong>Type:</strong> string</p><h4 id="isrootproject-rarr-boolean" tabindex="-1"><div class="jsdoc-object" id="isRootProject"><span class="type-signature"></span>isRootProject<span class="signature">()</span><span class="type-signature"> → {boolean}</span></div> <a class="header-anchor" href="#isrootproject-rarr-boolean" aria-label="Permalink to &quot;&lt;div class=&#39;jsdoc-object&#39; id=&#39;isRootProject&#39;&gt;&lt;span class=&quot;type-signature&quot;&gt;&lt;/span&gt;isRootProject&lt;span class=&quot;signature&quot;&gt;()&lt;/span&gt;&lt;span class=&quot;type-signature&quot;&gt; &amp;rarr; {boolean}&lt;/span&gt;&lt;/div&gt;&quot;">​</a></h4><p><strong>Description:</strong> Check whether the project currently being built is the root project.</p><p> This method is only available to custom task extensions defining <b>Specification Version 2.2 and above</b>.</p><p><strong>Source:</strong> <a href="https://github.com/UI5/cli/blob/main/packages//project/lib/build/helpers/TaskUtil.js" target="_blank" rel="noopener noreferrer">project/lib/build/helpers/TaskUtil.js</a>, <a href="https://github.com/UI5/cli/blob/main/packages//project/lib/build/helpers/TaskUtil.js#L236" target="_blank" rel="noopener noreferrer">line 236</a></p><h5 id="returns-6" tabindex="-1">Returns: <a class="header-anchor" href="#returns-6" aria-label="Permalink to &quot;Returns:&quot;">​</a></h5><p><code>true</code> if the currently built project is the root project</p><p><strong>Type:</strong> boolean</p><h4 id="registercleanuptask-callback" tabindex="-1"><div class="jsdoc-object" id="registerCleanupTask"><span class="type-signature"></span>registerCleanupTask<span class="signature">(callback)</span><span class="type-signature"></span></div> <a class="header-anchor" href="#registercleanuptask-callback" aria-label="Permalink to &quot;&lt;div class=&#39;jsdoc-object&#39; id=&#39;registerCleanupTask&#39;&gt;&lt;span class=&quot;type-signature&quot;&gt;&lt;/span&gt;registerCleanupTask&lt;span class=&quot;signature&quot;&gt;(callback)&lt;/span&gt;&lt;span class=&quot;type-signature&quot;&gt;&lt;/span&gt;&lt;/div&gt;&quot;">​</a></h4><p><strong>Description:</strong> Register a function that must be executed once the build is finished. This can be used to, for example, clean up files temporarily created on the file system. If the callback returns a Promise, it will be waited for. It will also be executed in cases where the build has failed or has been aborted.</p><p> This method is only available to custom task extensions defining <b>Specification Version 2.2 and above</b>.</p><p><strong>Source:</strong> <a href="https://github.com/UI5/cli/blob/main/packages//project/lib/build/helpers/TaskUtil.js" target="_blank" rel="noopener noreferrer">project/lib/build/helpers/TaskUtil.js</a>, <a href="https://github.com/UI5/cli/blob/main/packages//project/lib/build/helpers/TaskUtil.js#L275" target="_blank" rel="noopener noreferrer">line 275</a></p><h5 id="parameters-6" tabindex="-1">Parameters: <a class="header-anchor" href="#parameters-6" aria-label="Permalink to &quot;Parameters:&quot;">​</a></h5><table tabindex="0"><thead><tr><th>Name</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>callback</code></td><td><a href="@ui5_project_build_helpers_TaskUtil#~cleanupTaskCallback">@ui5/project/build/helpers/TaskUtil~cleanupTaskCallback</a></td><td>Callback to<br> register; it will be waited for if it returns a Promise</td></tr></tbody></table><h4 id="settag-resource-tag-valueopt" tabindex="-1"><div class="jsdoc-object" id="setTag"><span class="type-signature"></span>setTag<span class="signature">(resource, tag, value<span class="signature-attributes">opt</span>)</span><span class="type-signature"></span></div> <a class="header-anchor" href="#settag-resource-tag-valueopt" aria-label="Permalink to &quot;&lt;div class=&#39;jsdoc-object&#39; id=&#39;setTag&#39;&gt;&lt;span class=&quot;type-signature&quot;&gt;&lt;/span&gt;setTag&lt;span class=&quot;signature&quot;&gt;(resource, tag, value&lt;span class=&quot;signature-attributes&quot;&gt;opt&lt;/span&gt;)&lt;/span&gt;&lt;span class=&quot;type-signature&quot;&gt;&lt;/span&gt;&lt;/div&gt;&quot;">​</a></h4><p><strong>Description:</strong> Stores a tag with value for a given resource&#39;s path. Note that the tag is independent of the supplied resource instance. For two resource instances with the same path, the same tag value is returned. If the path of a resource is changed, any tag information previously stored for that resource is lost.</p><p> This method is only available to custom task extensions defining <b>Specification Version 2.2 and above</b>.</p><p><strong>Source:</strong> <a href="https://github.com/UI5/cli/blob/main/packages//project/lib/build/helpers/TaskUtil.js" target="_blank" rel="noopener noreferrer">project/lib/build/helpers/TaskUtil.js</a>, <a href="https://github.com/UI5/cli/blob/main/packages//project/lib/build/helpers/TaskUtil.js#L88" target="_blank" rel="noopener noreferrer">line 88</a></p><h5 id="parameters-7" tabindex="-1">Parameters: <a class="header-anchor" href="#parameters-7" aria-label="Permalink to &quot;Parameters:&quot;">​</a></h5><table tabindex="0"><thead><tr><th>Name</th><th>Type</th><th>Attributes</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>resource</code></td><td><a href="@ui5_fs_Resource">@ui5/fs/Resource</a></td><td></td><td></td><td>Resource-instance the tag should be stored for</td></tr><tr><td><code>tag</code></td><td>string</td><td></td><td></td><td>Name of the tag. Currently only the<br> <a href="@ui5_project_build_helpers_TaskUtil#STANDARD_TAGS">STANDARD_TAGS</a> are allowed</td></tr><tr><td><code>value</code></td><td>string | boolean | integer</td><td>optional</td><td><code>true</code></td><td>Tag value. Must be primitive</td></tr></tbody></table><h3 id="type-definitions" tabindex="-1">Type Definitions <a class="header-anchor" href="#type-definitions" aria-label="Permalink to &quot;Type Definitions&quot;">​</a></h3><h4 id="projectinterface" tabindex="-1"><div class="jsdoc-object" id="~ProjectInterface">ProjectInterface</div> <a class="header-anchor" href="#projectinterface" aria-label="Permalink to &quot;&lt;div class=&#39;jsdoc-object&#39; id=&#39;~ProjectInterface&#39;&gt;ProjectInterface&lt;/div&gt;&quot;">​</a></h4><p><strong>Description:</strong> Specification Version-dependent <a href="@ui5_project_specifications_Project">Project</a> interface. For details on individual functions, see <a href="@ui5_project_specifications_Project">Project</a></p><p><strong>Source:</strong> <a href="https://github.com/UI5/cli/blob/main/packages//project/lib/build/helpers/TaskUtil.js" target="_blank" rel="noopener noreferrer">project/lib/build/helpers/TaskUtil.js</a>, <a href="https://github.com/UI5/cli/blob/main/packages//project/lib/build/helpers/TaskUtil.js#L279" target="_blank" rel="noopener noreferrer">line 279</a></p><h5 id="properties" tabindex="-1">Properties: <a class="header-anchor" href="#properties" aria-label="Permalink to &quot;Properties:&quot;">​</a></h5><table class="props"><thead><tr><th>Name</th><th>Type</th><th class="last">Description</th></tr></thead><tbody><tr><td class="name"><code>getType</code></td><td class="type">function</td><td class="description last">Get the project type</td></tr><tr><td class="name"><code>getName</code></td><td class="type">function</td><td class="description last">Get the project name</td></tr><tr><td class="name"><code>getVersion</code></td><td class="type">function</td><td class="description last">Get the project version</td></tr><tr><td class="name"><code>getNamespace</code></td><td class="type">function</td><td class="description last">Get the project namespace</td></tr><tr><td class="name"><code>getRootReader</code></td><td class="type">function</td><td class="description last">Get the project rootReader</td></tr><tr><td class="name"><code>getReader</code></td><td class="type">function</td><td class="description last">Get the project reader</td></tr><tr><td class="name"><code>getRootPath</code></td><td class="type">function</td><td class="description last">Get the local File System path of the project&#39;s root directory</td></tr><tr><td class="name"><code>getSourcePath</code></td><td class="type">function</td><td class="description last">Get the local File System path of the project&#39;s source directory</td></tr><tr><td class="name"><code>getCustomConfiguration</code></td><td class="type">function</td><td class="description last">Get the project Custom Configuration</td></tr><tr><td class="name"><code>isFrameworkProject</code></td><td class="type">function</td><td class="description last">Check whether the project is a UI5-Framework project</td></tr><tr><td class="name"><code>getFrameworkName</code></td><td class="type">function</td><td class="description last">Get the project&#39;s framework name configuration</td></tr><tr><td class="name"><code>getFrameworkVersion</code></td><td class="type">function</td><td class="description last">Get the project&#39;s framework version configuration</td></tr><tr><td class="name"><code>getFrameworkDependencies</code></td><td class="type">function</td><td class="description last">Get the project&#39;s framework dependencies configuration</td></tr></tbody></table><p>Specification Version-dependent <a href="@ui5_project_specifications_Project">Project</a> interface. For details on individual functions, see <a href="@ui5_project_specifications_Project">Project</a></p><h5 id="type-2" tabindex="-1">Type: <a class="header-anchor" href="#type-2" aria-label="Permalink to &quot;Type:&quot;">​</a></h5><ul><li>object</li></ul><h4 id="standardbuildtags" tabindex="-1"><div class="jsdoc-object" id="~StandardBuildTags">StandardBuildTags</div> <a class="header-anchor" href="#standardbuildtags" aria-label="Permalink to &quot;&lt;div class=&#39;jsdoc-object&#39; id=&#39;~StandardBuildTags&#39;&gt;StandardBuildTags&lt;/div&gt;&quot;">​</a></h4><p><strong>Description:</strong> Standard Build Tags. See UI5 CLI <a href="https://github.com/UI5/cli/blob/main/rfcs/0008-resource-tagging-during-build.md">RFC 0008</a> for details.</p><p><strong>Source:</strong> <a href="https://github.com/UI5/cli/blob/main/packages//project/lib/build/helpers/TaskUtil.js" target="_blank" rel="noopener noreferrer">project/lib/build/helpers/TaskUtil.js</a>, <a href="https://github.com/UI5/cli/blob/main/packages//project/lib/build/helpers/TaskUtil.js#L26" target="_blank" rel="noopener noreferrer">line 26</a></p><h5 id="properties-1" tabindex="-1">Properties: <a class="header-anchor" href="#properties-1" aria-label="Permalink to &quot;Properties:&quot;">​</a></h5><table class="props"><thead><tr><th>Name</th><th>Type</th><th class="last">Description</th></tr></thead><tbody><tr><td class="name"><code>OmitFromBuildResult</code></td><td class="type">string</td><td class="description last">Setting this tag to true will prevent the resource from being written to the build target directory</td></tr><tr><td class="name"><code>IsBundle</code></td><td class="type">string</td><td class="description last">This tag identifies resources that contain (i.e. bundle) multiple other resources</td></tr><tr><td class="name"><code>IsDebugVariant</code></td><td class="type">string</td><td class="description last">This tag identifies resources that are a debug variant (typically named with a &quot;-dbg&quot; suffix)<br> of another resource. This tag is visible to other projects</td></tr><tr><td class="name"><code>HasDebugVariant</code></td><td class="type">string</td><td class="description last">This tag identifies resources for which a debug variant has been created.<br> This tag is visible to other projects</td></tr></tbody></table><p>Standard Build Tags. See UI5 CLI <a href="https://github.com/UI5/cli/blob/main/rfcs/0008-resource-tagging-during-build.md">RFC 0008</a> for details.</p><h5 id="type-3" tabindex="-1">Type: <a class="header-anchor" href="#type-3" aria-label="Permalink to &quot;Type:&quot;">​</a></h5><ul><li>object</li></ul><h4 id="cleanuptaskcallback-force" tabindex="-1"><div class="jsdoc-object" id="~cleanupTaskCallback"><span class="type-signature"></span>cleanupTaskCallback<span class="signature">(force)</span><span class="type-signature"></span></div> <a class="header-anchor" href="#cleanuptaskcallback-force" aria-label="Permalink to &quot;&lt;div class=&#39;jsdoc-object&#39; id=&#39;~cleanupTaskCallback&#39;&gt;&lt;span class=&quot;type-signature&quot;&gt;&lt;/span&gt;cleanupTaskCallback&lt;span class=&quot;signature&quot;&gt;(force)&lt;/span&gt;&lt;span class=&quot;type-signature&quot;&gt;&lt;/span&gt;&lt;/div&gt;&quot;">​</a></h4><p><strong>Description:</strong> Callback that is executed once the build has finished</p><p><strong>Source:</strong> <a href="https://github.com/UI5/cli/blob/main/packages//project/lib/build/helpers/TaskUtil.js" target="_blank" rel="noopener noreferrer">project/lib/build/helpers/TaskUtil.js</a>, <a href="https://github.com/UI5/cli/blob/main/packages//project/lib/build/helpers/TaskUtil.js#L252" target="_blank" rel="noopener noreferrer">line 252</a></p><h5 id="parameters-8" tabindex="-1">Parameters: <a class="header-anchor" href="#parameters-8" aria-label="Permalink to &quot;Parameters:&quot;">​</a></h5><table tabindex="0"><thead><tr><th>Name</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>force</code></td><td>boolean</td><td>Whether the cleanup callback should<br> gracefully wait for certain jobs to be completed (<code>false</code>)<br> or enforce immediate termination (<code>true</code>)</td></tr></tbody></table><h4 id="resourcefactory" tabindex="-1"><div class="jsdoc-object" id="~resourceFactory">resourceFactory</div> <a class="header-anchor" href="#resourcefactory" aria-label="Permalink to &quot;&lt;div class=&#39;jsdoc-object&#39; id=&#39;~resourceFactory&#39;&gt;resourceFactory&lt;/div&gt;&quot;">​</a></h4><p><strong>Description:</strong> Specification Version-dependent set of @ui5/fs/resourceFactory functions provided to tasks. For details on individual functions, see @ui5/fs/resourceFactory</p><p><strong>Source:</strong> <a href="https://github.com/UI5/cli/blob/main/packages//project/lib/build/helpers/TaskUtil.js" target="_blank" rel="noopener noreferrer">project/lib/build/helpers/TaskUtil.js</a>, <a href="https://github.com/UI5/cli/blob/main/packages//project/lib/build/helpers/TaskUtil.js#L346" target="_blank" rel="noopener noreferrer">line 346</a></p><h5 id="properties-2" tabindex="-1">Properties: <a class="header-anchor" href="#properties-2" aria-label="Permalink to &quot;Properties:&quot;">​</a></h5><table class="props"><thead><tr><th>Name</th><th>Type</th><th class="last">Description</th></tr></thead><tbody><tr><td class="name"><code>createResource</code></td><td class="type">function</td><td class="description last">Creates a <a href="@ui5_fs_Resource">Resource</a>.<br> Accepts the same parameters as the <a href="@ui5_fs_Resource">Resource</a> constructor.</td></tr><tr><td class="name"><code>createReaderCollection</code></td><td class="type">function</td><td class="description last">Creates a reader collection:<br> <a href="@ui5_fs_ReaderCollection">ReaderCollection</a></td></tr><tr><td class="name"><code>createReaderCollectionPrioritized</code></td><td class="type">function</td><td class="description last">Creates a prioritized reader collection:<br> <a href="@ui5_fs_ReaderCollectionPrioritized">ReaderCollectionPrioritized</a></td></tr><tr><td class="name"><code>createFilterReader</code></td><td class="type">function</td><td class="description last">Create a <a href="@ui5_fs_readers_Filter">Filter-Reader</a> with the given reader.</td></tr><tr><td class="name"><code>createLinkReader</code></td><td class="type">function</td><td class="description last">Create a <a href="@ui5_fs_readers_Filter">Link-Reader</a> with the given reader.</td></tr><tr><td class="name"><code>createFlatReader</code></td><td class="type">function</td><td class="description last">Create a <a href="@ui5_fs_readers_Link">Link-Reader</a><br>where all requests are prefixed with <code>/resources/&lt;namespace&gt;</code>.</td></tr></tbody></table><p>Specification Version-dependent set of @ui5/fs/resourceFactory functions provided to tasks. For details on individual functions, see @ui5/fs/resourceFactory</p><h5 id="type-4" tabindex="-1">Type: <a class="header-anchor" href="#type-4" aria-label="Permalink to &quot;Type:&quot;">​</a></h5><ul><li>object</li></ul>',137)])])}const b=t(o,[["render",i]]);export{h as __pageData,b as default};
